        {/* Ground Contact Shadow */}
        <ContactShadows
          position={[0, 0.01, 0]}
          opacity={0.5}
          scale={14}
          blur={2.5}
          far={6}
        />

        {/* Orbit Controls */}
        {enabled && (
          <OrbitControls
            ref={controlsRef}
            makeDefault
